    /// ⌘D — copies land after the originals' span; ⌥-dragging then moves
    /// them, which is the same op with a `move_clip` behind it.
    func duplicateSelection() {
        guard let document = document, !document.selection.isEmpty else {
            NSSound.beep()
            return
        }
        document.applyEdit("Duplicate", .duplicate(clips: Array(document.selection)))
    }

    /// ⇧⌘F — one still clip filling a gap opened at the playhead.
    func freezeSelection() {
        guard let document = document, let clip = clipsUnderPlayhead.first else {
            NSSound.beep()
            return
        }
        document.applyEdit("Freeze Frame", .freezeFrame(clip: clip.id, at: document.playhead))
    }

    /// ⌥⌘D — the audio moves to its own clip on the track below.
    func detachSelectionAudio() {
        guard let document = document, !selectedClips.isEmpty else {
            NSSound.beep()
            return
        }
        document.applyEdit("Detach Audio", selectedClips.map { .detachAudio(clip: $0.id) })
    }

    /// ⇧⌥⌘D — Clip ▸ Attach Audio and the Mix section's button: each linked
    /// pair the selection touches merges back into one clip (spec §11 AU-95).
    @objc func attachAudio(_ sender: Any?) { attachSelectionAudio() }

    /// One `attach_audio` per PAIR, so a selection holding both halves of a
    /// pair asks once. The core refuses a pair out of step in its own
    /// sentence; a selection with no linked clip beeps.
    func attachSelectionAudio() {
        guard let document = document else { return }
        var seen: Set<UInt32> = []
        var ops: [ReelOp] = []
        for clip in selectedClips {
            guard let partner = clip.linked, !seen.contains(clip.id) else { continue }
            seen.formUnion([clip.id, partner])
            ops.append(.attachAudio(clip: clip.id))
        }
        guard !ops.isEmpty else {
            NSSound.beep()
            return
        }
        document.applyEdit("Attach Audio", ops)
    }

